SELECT pg_temp.expect_failure('INSERT INTO role_permissions (role_id,permission_id) SELECT role_id,permission_id FROM role_permissions LIMIT 1','23505','duplicate global role permission rejected');
SELECT pg_temp.expect_failure('INSERT INTO vulnerability_aliases (vulnerability_id,alias_type,value) VALUES (''e47ca149-6f2c-5ab8-a5a6-48cd0a5b76a8'',''FIXTURE'',''CVE-FIXTURE'')','23505','duplicate vulnerability alias rejected');
SELECT pg_temp.expect_failure('INSERT INTO vulnerability_references (vulnerability_id,reference_type,url) VALUES (''e47ca149-6f2c-5ab8-a5a6-48cd0a5b76a8'',''ADVISORY'',''https://example.invalid/advisory'')','23505','duplicate advisory reference rejected');
SELECT pg_temp.expect_failure('UPDATE audit_events SET action=''admin-change'' WHERE id=''86541b65-c416-5afd-a42a-ec22b3c86770''','42501','audit trigger also rejects administrative mutation');
SET LOCAL ROLE dependency_app;
SELECT set_config('app.organization_id','10e4c11d-6888-5d03-a540-766b38437f71',true);
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM document_repositories),'document can refer to multiple repositories without arrays');
