SELECT pg_temp.expect_failure('INSERT INTO document_chunks (id,organization_id,document_version_id,ordinal,content,content_hash) VALUES (''7e1c3bfe-e555-5176-8258-25662d859bb9'',''10e4c11d-6888-5d03-a540-766b38437f71'',''fd0499d6-50e5-5eb4-8a1d-b7cce49ec8d9'',0,''duplicate'',''cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc'')','23505','duplicate document ordinal rejected');
SELECT pg_temp.expect_failure('INSERT INTO assistant_message_evidences (id,organization_id,message_id,document_chunk_id,citation_ordinal) VALUES (''beb0d6a1-1599-5213-96cc-f1602e372a8f'',''10e4c11d-6888-5d03-a540-766b38437f71'',''ff2bd7eb-4467-50fa-9f20-6c106759a401'',''0070e45e-20d5-5a15-9c4d-138d76551f16'',2)','23503','assistant citation cannot refer to foreign tenant');
SELECT pg_temp.expect_failure('INSERT INTO assistant_message_evidences (id,organization_id,message_id,citation_ordinal) VALUES (''1404d5e0-ad8f-5c58-95cd-14d1dd7a1db4'',''10e4c11d-6888-5d03-a540-766b38437f71'',''ff2bd7eb-4467-50fa-9f20-6c106759a401'',2)','23514','citation must reference exactly one typed source');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM notification_deliveries),'one notification has independent channel deliveries');
SELECT pg_temp.expect_failure('INSERT INTO notification_deliveries (id,organization_id,notification_id,channel_id,recipient_membership_id) VALUES (''5bdecd9d-d2f4-5d29-9379-d5969935f62c'',''10e4c11d-6888-5d03-a540-766b38437f71'',''05b82fdb-5b4f-53a3-8c9e-36898f48feac'',(SELECT id FROM notification_channels WHERE code=''EMAIL''),''634382e7-88e8-564a-905a-1fcab89a0e96'')','23505','duplicate notification delivery rejected');
SELECT pg_temp.expect_failure('INSERT INTO notification_deliveries (id,organization_id,notification_id,channel_id,recipient_membership_id) VALUES (''c932bae4-2168-5de7-975c-6a10b88bbc5c'',''10e4c11d-6888-5d03-a540-766b38437f71'',''05b82fdb-5b4f-53a3-8c9e-36898f48feac'',(SELECT id FROM notification_channels WHERE code=''EMAIL''),''95d1876c-e639-546f-9b20-d03f25a249cc'')','23503','notification delivery cannot cross tenants');
